            return str > target ? str : '';
        }

        const pos = target.charCodeAt(targetPos) - 97;

        if (freq[pos] > 0) {
            freq[pos]--;

            const same = gogo(freq, targetPos + 1, str + String.fromCharCode(pos + 97));
