        let res = '';

        for (let i = pos + 1; i < 26; i++) {
            if (freq[i] > 0) {
                freq[i]--;
                return fill(freq, str + String.fromCharCode(i + 97));
            }
        }

        return res;
    };

    return gogo(freq, 0, '');
};

/**
 * @param {string} s
 * @param {string} target
 * @return {string}
 */
var lexGreaterPermutation = function(s, target) {
    const freq = Array(26).fill(0);

    for (let i = 0; i < s.length; i++) {
        freq[s.charCodeAt(i) - 97]++;
    }

    const fill = (str) => {
        for (let i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                str += String.fromCharCode(i + 97).repeat(freq[i]);
            }
        }
        return str;
    };

    const dfs = (pos, str) => {
        if (pos === target.length) {
            return str > target ? str : '';
        }

        const start = target.charCodeAt(pos) - 97;

        for (let i = start; i < 26; i++) {
            if (freq[i] > 0) {
                freq[i]--;

                const newStr = str + String.fromCharCode(i + 97);

                if (i > start) {
                    return fill(newStr);
                }

                const goDeeper = dfs(pos + 1, newStr);
                if (goDeeper) {
                    return goDeeper;
                }

                freq[i]++;
            }
        }

        return '';
    };

    return dfs(0, '');
};
